// tidy trims user-typed text and squashes inner whitespace. It keeps the original case.
function tidy(s) {
  return String(s).trim().replace(/\s+/g, ' ');
}

// clean is tidy plus lowercasing, for comparisons and handles.
function clean(s) {
  return tidy(s).toLowerCase();
}

module.exports = { tidy, clean };

